def render(sections):
    out = []
    for h, blocks in sections:
        out.append(f"<h2>{h}</h2>")
        for b in blocks:
            out.append("<ul>" + "".join(f"<li>{x}</li>" for x in b) + "</ul>" if isinstance(b, list) else f"<p>{b}</p>")
    return "".join(out)
